        "selector": "main > article:nth-of-type(1) > section:nth-of-type(1) > h3:nth-of-type(2)",
        "textIndex": 0,
        "kind": "text",
        "lt": "VEIKLA",
        "group_lt": "Misija, veikla ir bendruomenė",
